 * Since: 2.0.0
 **/
gboolean
fu_input_stream_read_u16(GInputStream *stream,
                         gsize offset,
                         guint16 *value,
                         FuEndianType endian,
                         GError **error)
{
        guint8 buf[2] = {0};
        g_return_val_if_fail(G_IS_INPUT_STREAM(stream), FALSE);
